// ---- Build a plain-text alert for any failed Review Pulse execution ----
const e = $('Error Trigger').first().json;
const cfg = Object.fromEntries($('Read config').all(0, 0).map(i => [i.json.key, String(i.json.value ?? '')]));
const ex = e.execution || {}, wf = e.workflow || {};
const msg = ex.error?.message || e.trigger?.error?.message || 'Unknown error';
const node = ex.lastNodeExecuted || ex.error?.node?.name || '–';
const ist = new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 16).replace('T', ' ');
const runMatch = String(msg).match(/\d{4}-W\d{2}/);
return [{ json: {
  to: cfg.approver_email,
  subject: `⚠ Review Pulse failed: ${wf.name || 'workflow'}${runMatch ? ' – ' + runMatch[0] : ''}`,
  message: [
    `A Review Pulse workflow stopped at ${ist} IST.`, '',
    `Workflow: ${wf.name || '–'}`,
    `Step: ${node}`,
    `Reason: ${msg}`, '',
    ex.url ? `Open the execution: ${ex.url}` : '',
    'Status of every week is in the runs tab of Review_Pulse_DB.',
    'Nothing was sent to anyone; no Doc entry or draft is created without your approval.',
  ].filter(l => l !== null).join('\n'),
}}];
